using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;

public static class CleanupProbe {
 static void Check(bool value,string label){if(!value)throw new Exception(label);}
 static void Proof(string data,string generation,string key){string payload=HostCore.Json.Serialize(new{generation=generation,readSucceeded=true,transport="official-secure-tunnel",fixture=true,notRealHostEvidence=true});string mac;using(var h=new HMACSHA256(Encoding.UTF8.GetBytes(key)))mac=HostCore.Hex(h.ComputeHash(Encoding.UTF8.GetBytes(payload)));HostCore.Save(Path.Combine(data,"first-use-proof.json"),new{payload=payload,mac=mac});}
 public static int Main(string[] args){try{
  string root=HostCore.Full(args[0]);Check(root.IndexOf(".ygpt-local-tests",StringComparison.OrdinalIgnoreCase)>=0,"Named disposable test root required");Directory.CreateDirectory(root);string data=Path.Combine(root,"data"),install=Path.Combine(root,"install"),downloads=Path.Combine(root,"downloads");Directory.CreateDirectory(install);Directory.CreateDirectory(downloads);HostCore.PrivateDirectory(data);string key=HostCore.NewKey();HostCore.SaveSecrets(data,new Dictionary<string,object>{{"verificationKey",key},{"localKey",HostCore.NewKey()}});string generation=Guid.NewGuid().ToString("N");
  string owned=Path.Combine(downloads,"owned.bin"),changed=Path.Combine(downloads,"changed.bin"),held=Path.Combine(downloads,"held.bin"),unknown=Path.Combine(downloads,"user-file.bin"),replacement=Path.Combine(downloads,"replacement.bin"),unconsented=Path.Combine(downloads,"setup.exe"),required=Path.Combine(install,"settings.exe");foreach(string p in new[]{owned,changed,held,unknown,replacement,unconsented,required})File.WriteAllText(p,"ORIGINAL");
  var entries=new List<Dictionary<string,object>>();foreach(string p in new[]{owned,changed,held,replacement})entries.Add(InstallCleanup.Entry(p,generation,"install-cache",downloads,false));var download=InstallCleanup.Entry(unconsented,generation,"setup-download",downloads,true);download["explicitFileConsent"]=false;entries.Add(download);var retained=InstallCleanup.Entry(required,generation,"install-cache",root,false);retained["neededByMaintenance"]=true;entries.Add(retained);
  InstallCleanup.Record(data,install,generation,entries,false,Int32.MaxValue,0);Check(HostCore.S(InstallCleanup.Run(data,install),"state")=="not-authorized","Consent gate");
  InstallCleanup.Record(data,install,generation,entries,true,Int32.MaxValue,0);Check(HostCore.S(InstallCleanup.Run(data,install),"state")=="awaiting-real-first-use","First-use gate");
  Proof(data,"wrong-generation",key);Check(HostCore.S(InstallCleanup.Run(data,install),"state")=="awaiting-real-first-use","Generation gate");Proof(data,generation,key);
  InstallCleanup.Record(data,install,generation,entries,true,System.Diagnostics.Process.GetCurrentProcess().Id,System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks);Check(HostCore.S(InstallCleanup.Run(data,install),"state")=="waiting-for-setup-exit","Setup-exit gate");InstallCleanup.Record(data,install,generation,entries,true,Int32.MaxValue,0);
  string normal=Path.Combine(downloads,"ordinary"),moved=Path.Combine(downloads,"moved-original");Directory.CreateDirectory(normal);string junctionFile=Path.Combine(normal,"same.bin");File.WriteAllText(junctionFile,"KEEP_LINK_TARGET");entries.Add(InstallCleanup.Entry(junctionFile,generation,"install-cache",downloads,false));Directory.Move(normal,moved);
  using(var mk=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("cmd.exe","/d /c mklink /J "+HostCore.Q(normal)+" "+HostCore.Q(moved)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){mk.WaitForExit();Check(mk.ExitCode==0,"Junction fixture created");}
  string foreign=Path.Combine(downloads,"foreign.bin");File.WriteAllText(foreign,"FOREIGN");entries.Add(InstallCleanup.Entry(foreign,"another-generation","install-cache",downloads,false));
  string absent=Path.Combine(downloads,"already-absent.bin");File.WriteAllText(absent,"absent");entries.Add(InstallCleanup.Entry(absent,generation,"staging",downloads,false));File.Delete(absent);
  var systemGuard=new Dictionary<string,object>(entries[0]);systemGuard["normalizedAbsolutePath"]=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"not-a-real-ygpt-file");entries.Add(systemGuard);
  var secretHash=HostCore.Hash(Path.Combine(data,"credentials.dpapi"));InstallCleanup.Record(data,install,generation,entries,true,Int32.MaxValue,0);Check(HostCore.S(InstallCleanup.Run(data,install),"state")=="awaiting-live-connection","Missing live connection gate");
  HostCore.Save(Path.Combine(data,"connection.json"),new{mode="secure-tunnel",fixtureOnly=true});HostCore.Save(Path.Combine(data,"watchdog-health.json"),new{ownerId=HostCore.OwnerId(data),localReady=true,tunnelConnected=true,pid=System.Diagnostics.Process.GetCurrentProcess().Id,birth=System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks,at=DateTime.UtcNow.ToString("o"),fixtureOnly=true,notRealChatGPT=true});
  File.WriteAllText(changed,"MODIFIED");File.Move(replacement,replacement+".before");File.WriteAllText(replacement,"ORIGINAL");
  Dictionary<string,object> receipt;using(var lockFile=new FileStream(held,FileMode.Open,FileAccess.Read,FileShare.Read)){receipt=InstallCleanup.Run(data,install);}
  Check(!File.Exists(owned),"Known owned file deleted");Check(File.ReadAllText(changed)=="MODIFIED","Changed file retained");Check(File.Exists(held),"In-use file retained");Check(File.Exists(unknown),"Unknown sibling retained");Check(File.Exists(replacement),"Replaced identity retained");Check(File.Exists(unconsented),"Unconsented source download retained");Check(File.Exists(required),"Settings retained");Check(Convert.ToInt32(receipt["deleted"])==1,"Exactly one deletion");
  Check(File.ReadAllText(Path.Combine(moved,"same.bin"))=="KEEP_LINK_TARGET","Junction target retained");Check(File.ReadAllText(foreign)=="FOREIGN","Foreign generation retained");Check(HostCore.Hash(Path.Combine(data,"credentials.dpapi"))==secretHash,"Credential ciphertext unchanged");
  var retried=InstallCleanup.Run(data,install);Check(Convert.ToInt32(retried["deleted"])==1&&Convert.ToInt32(retried["totalDeleted"])==2,"Retry finishes only the previously locked file and preserves cumulative accounting");Check(Convert.ToInt32(InstallCleanup.Run(data,install)["deleted"])==0,"Replay makes no additional deletion");
  var tampered=HostCore.Read(Path.Combine(data,"installation-ownership.json"));tampered["signedPayload"]=HostCore.S(tampered,"signedPayload")+" ";HostCore.Save(Path.Combine(data,"installation-ownership.json"),tampered);bool rejected=false;try{InstallCleanup.Run(data,install);}catch{rejected=true;}Check(rejected,"Manifest MAC rejects tampering");
  Console.WriteLine(HostCore.Json.Serialize(new{passed=true,source="native Windows cleanup against explicitly disposable fixture files",realChatGPT=false,checks=new[]{"consent","first-use gate","generation binding","setup exit","exact owned deletion","modified retained","in-use retained","unknown retained","replacement retained","download consent","maintenance retained","junction retained","foreign generation","credential hash","system root guard","already absent","retry accounting","replay idempotent","manifest tamper rejected"},receipt=receipt,retryReceipt=retried}));return 0;
 }catch(Exception e){Console.WriteLine(HostCore.Json.Serialize(new{passed=false,message=e.Message}));return 1;}}
}
